   501→        pattern.frequency = 5;
   502→
   503→        let probability = calc.calculate_pattern_probability(&pattern);
   504→        assert!(probability > 0.0 && probability < 1.0);
   505→    }
   506→
   507→    #[test]
   508→    fn test_pattern_actionability() {
   509→        let calc = ProbabilityCalculator::new();
   510→        let mut pattern = RecoveryPattern::new("MemoryLeak".to_string());
   511→        pattern.confidence = 0.75;
   512→        pattern.success_rate = 0.70;
   513→        pattern.frequency = 3;
   514→
   515→        assert!(calc.is_pattern_actionable(&pattern));
   516→    }
   517→}
