   148→// Part 2: 인터럽트 프레임 (Interrupt Frame)
   149→// ============================================================================
   150→
   151→/// CPU가 인터럽트 발생 시 저장하는 정보
   152→pub struct InterruptFrame {
   153→    /// 인터럽트 벡터 번호
   154→    pub vector: u8,
   155→
   156→    /// 에러 코드 (없으면 0)
   157→    pub error_code: u64,
   158→
   159→    /// RIP (Instruction Pointer) - 인터럽트 발생 시점의 명령어
   160→    pub rip: u64,
   161→
   162→    /// CS (Code Segment)
   163→    pub cs: u64,
   164→
   165→    /// RFLAGS (프로세서 플래그)
   166→    pub rflags: u64,
   167→
   168→    /// RSP (Stack Pointer)
   169→    pub rsp: u64,
   170→
   171→    /// SS (Stack Segment)
   172→    pub ss: u64,
   173→
   174→    /// 추가 정보: 발생 시간 (시뮬레이션 틱)
   175→    pub timestamp: u32,
   176→
   177→    /// 추가 정보: 발생 카운트
   178→    pub occurrence_count: u32,
   179→}
   180→
   181→impl InterruptFrame {
   182→    pub fn new(vector: u8, error_code: u64, rip: u64) -> Self {
   183→        InterruptFrame {
   184→            vector,
   185→            error_code,
   186→            rip,
   187→            cs: 0x08,      // 커널 코드 세그먼트
   188→            rflags: 0x202, // IF 플래그 설정
   189→            rsp: 0x7FFF0000,
   190→            ss: 0x10,      // 커널 스택 세그먼트
   191→            timestamp: 0,
   192→            occurrence_count: 0,
   193→        }
   194→    }
   195→
   196→    pub fn print_frame(&self) {
   197→        println!("\n📋 Interrupt Frame:");
   198→        println!("  Vector: {} (0x{:02x})", self.vector, self.vector);
   199→        println!("  Error Code: 0x{:016x}", self.error_code);
   200→        println!("  RIP: 0x{:016x}", self.rip);
   201→        println!("  CS: 0x{:04x} | SS: 0x{:04x}", self.cs, self.ss);
   202→        println!("  RSP: 0x{:016x}", self.rsp);
   203→        println!("  RFLAGS: 0x{:08x}", self.rflags);
   204→        println!("  Timestamp: {} | Count: {}", self.timestamp, self.occurrence_count);
   205→    }
   206→}
