   208→// ============================================================================
   209→// Part 3: 인터럽트 디스크립터 테이블 (IDT) 항목
   210→// ============================================================================
   211→
   212→/// IDT 항목 (게이트 디스크립터)
   213→pub struct IDTEntry {
   214→    /// 오프셋 (핸들러 주소)
   215→    pub offset: u64,
   216→
   217→    /// 세그먼트 선택자 (코드 세그먼트)
   218→    pub segment_selector: u16,
   219→
   220→    /// 플래그 (타입, DPL, 존재 여부)
   221→    pub flags: u8,
   222→
   223→    /// 이 항목의 벡터 번호
   224→    pub vector: u8,
   225→
   226→    /// 설정된 여부
   227→    pub present: bool,
   228→
   229→    /// 특권 레벨 (DPL, 0-3)
   230→    pub privilege_level: u8,
   231→
   232→    /// 게이트 타입 (Interrupt Gate, Trap Gate)
   233→    pub gate_type: GateType,
   234→
   235→    /// 핸들러 함수 포인터 (시뮬레이션용)
   236→    pub handler_id: u32,
   237→}
   238→
   239→#[derive(Clone, Copy, Debug)]
   240→pub enum GateType {
   241→    InterruptGate,  // 인터럽트 발생 시 IF 플래그 자동 클리어
   242→    TrapGate,       // IF 플래그 유지
   243→}
   244→
   245→impl IDTEntry {
   246→    pub fn new(vector: u8, offset: u64, handler_id: u32) -> Self {
   247→        IDTEntry {
   248→            offset,
   249→            segment_selector: 0x08,  // 커널 코드 세그먼트
   250→            flags: 0x8E,             // Present, DPL=0, Type=Interrupt Gate
   251→            vector,
   252→            present: true,
   253→            privilege_level: 0,
   254→            gate_type: GateType::InterruptGate,
   255→            handler_id,
   256→        }
   257→    }
   258→
   259→    pub fn set_user_accessible(&mut self) {
   260→        self.privilege_level = 3;  // 사용자 모드 접근 가능
   261→    }
   262→
   263→    pub fn print_entry(&self) {
   264→        println!("  [Vector {}] Offset: 0x{:016x}, Handler: {}, Present: {}",
   265→                 self.vector, self.offset, self.handler_id, self.present);
   266→    }
   267→}
