   269→// ============================================================================
   270→// Part 4: IDT (인터럽트 디스크립터 테이블)
   271→// ============================================================================
   272→
   273→/// Interrupt Descriptor Table (최대 256개 항목)
   274→pub struct IDT {
   275→    /// 256개의 IDT 항목
   276→    pub entries: Vec<IDTEntry>,
   277→
   278→    /// 로드된 여부
   279→    pub loaded: bool,
   280→
   281→    /// 처리된 인터럽트 수
   282→    pub total_interrupts: u64,
   283→
   284→    /// 핸들러 매핑
   285→    pub handlers: Vec<Option<u32>>,
   286→}
   287→
   288→impl IDT {
   289→    pub fn new() -> Self {
   290→        let mut idt = IDT {
   291→            entries: Vec::new(),
   292→            loaded: false,
   293→            total_interrupts: 0,
   294→            handlers: vec![None; 256],
   295→        };
   296→
   297→        // 기본 예외 핸들러 설정
   298→        for i in 0..20 {
   299→            let entry = IDTEntry::new(i as u8, 0x100000 + (i * 0x100) as u64, i as u32);
   300→            idt.entries.push(entry);
   301→        }
   302→
   303→        // 하드웨어 인터럽트 (IRQ 0-15)
   304→        for i in 0..16 {
   305→            let entry = IDTEntry::new(32 + i as u8, 0x200000 + (i * 0x100) as u64, 100 + i as u32);
   306→            idt.entries.push(entry);
   307→        }
   308→
   309→        // 시스템 호출 (0x80)
   310→        let mut syscall_entry = IDTEntry::new(128, 0x300000, 200);
   311→        syscall_entry.set_user_accessible();
   312→        idt.entries.push(syscall_entry);
   313→
   314→        idt
   315→    }
   316→
   317→    pub fn load(&mut self) -> Result<(), String> {
   318→        if self.entries.is_empty() {
   319→            return Err("IDT is empty".to_string());
   320→        }
   321→
   322→        self.loaded = true;
   323→        println!("✅ IDT loaded with {} entries", self.entries.len());
   324→        Ok(())
   325→    }
   326→
   327→    pub fn register_handler(&mut self, vector: u8, handler_id: u32) -> Result<(), String> {
   328→        if vector as usize >= 256 {
   329→            return Err(format!("Invalid vector number: {}", vector));
   330→        }
   331→
   332→        self.handlers[vector as usize] = Some(handler_id);
   333→
   334→        // 기존 항목 업데이트 또는 새 항목 생성
   335→        for entry in &mut self.entries {
   336→            if entry.vector == vector {
   337→                entry.handler_id = handler_id;
   338→                return Ok(());
   339→            }
   340→        }
   341→
   342→        // 새 항목 생성
   343→        let entry = IDTEntry::new(vector, 0x100000, handler_id);
   344→        self.entries.push(entry);
   345→        Ok(())
   346→    }
   347→
   348→    pub fn get_handler(&self, vector: u8) -> Option<u32> {
   349→        if vector as usize < self.handlers.len() {
   350→            self.handlers[vector as usize]
   351→        } else {
   352→            None
   353→        }
   354→    }
   355→
   356→    pub fn print_idt(&self) {
   357→        println!("\n╔════════════════════════════════════════════════════════════╗");
   358→        println!("║         Interrupt Descriptor Table (IDT) Status            ║");
   359→        println!("╚════════════════════════════════════════════════════════════╝");
   360→
   361→        println!("\nStatus: {} | Entries: {}",
   362→                 if self.loaded { "LOADED" } else { "NOT LOADED" },
   363→                 self.entries.len());
   364→
   365→        println!("\nException Handlers (0-19):");
   366→        for i in 0..20.min(self.entries.len()) {
   367→            self.entries[i].print_entry();
   368→        }
   369→
   370→        println!("\nHardware Interrupts (32-47):");
   371→        for i in 32..48.min(self.entries.len()) {
   372→            if i < self.entries.len() {
   373→                self.entries[i].print_entry();
   374→            }
   375→        }
   376→
   377→        println!("\nSystem Call Handler (128):");
   378→        for entry in &self.entries {
   379→            if entry.vector == 128 {
   380→                entry.print_entry();
   381→            }
   382→        }
   383→    }
   384→}
