   486→
   487→pub fn main() {
   488→    println!("╔════════════════════════════════════════════════════════════╗");
   489→    println!("║    FreeLang OS Kernel - Phase G Week 3 Interrupts         ║");
   490→    println!("╚════════════════════════════════════════════════════════════╝\n");
   491→
   492→    // IDT 생성 및 로드
   493→    println!("🔧 Setting up IDT...");
   494→    let mut idt = IDT::new();
   495→    idt.load().unwrap();
   496→
   497→    // 인터럽트 핸들러 생성
   498→    let mut handler = InterruptHandler::new();
   499→
   500→    // 몇 가지 인터럽트 처리
   501→    println!("\n⚡ Handling interrupts...\n");
   502→
   503→    // 1. 하드웨어 인터럽트 (타이머)
   504→    let frame = InterruptFrame::new(32, 0, 0x100000);
   505→    handler.handle_interrupt(InterruptType::HardwareInterrupt { irq: 0 }, frame).ok();
   506→
   507→    // 2. 하드웨어 인터럽트 (키보드)
   508→    let frame = InterruptFrame::new(33, 0, 0x100100);
   509→    handler.handle_interrupt(InterruptType::HardwareInterrupt { irq: 1 }, frame).ok();
   510→
   511→    // 3. 시스템 호출
   512→    let frame = InterruptFrame::new(128, 0, 0x100200);
   513→    handler.handle_interrupt(InterruptType::SystemCall, frame).ok();
   514→
   515→    // 4. 페이지 폴트
   516→    let mut frame = InterruptFrame::new(14, 0x500000, 0x100300);
   517→    frame.error_code = 0x04;  // 존재하지 않는 페이지
   518→    let result = handler.handle_interrupt(InterruptType::PageFault, frame);
   519→    println!("   Result: {:?}", result);
   520→
   521→    // 5. 0으로 나누기
   522→    let frame = InterruptFrame::new(0, 0, 0x100400);
   523→    let result = handler.handle_interrupt(InterruptType::DivideError, frame);
   524→    println!("   Result: {:?}", result);
   525→
   526→    // IDT 상태 출력
   527→    idt.print_idt();
   528→
   529→    // 통계 출력
   530→    handler.print_statistics();
   531→
   532→    if let Some(frame) = &handler.last_frame {
   533→        frame.print_frame();
   534→    }
   535→
   536→    println!("\n✨ Interrupt handling simulation complete!\n");
   537→}
