   214→// ============================================================================
   215→// StateTransitionLog: 상태 전이 로그
   216→// ============================================================================
   217→
   218→struct StateTransition {
   219→    pattern_id: u32,
   220→    timestamp: u64,
   221→    from_state: String,
   222→    to_state: String,
   223→    frequency_at_transition: u32,
   224→    confidence_at_transition: f64,
   225→    reason: String,
   226→}
   227→
   228→impl StateTransition {
   229→    fn new(
   230→        pattern_id: u32,
   231→        timestamp: u64,
   232→        from_state: String,
   233→        to_state: String,
   234→        frequency: u32,
   235→        confidence: f64,
   236→        reason: String,
   237→    ) -> StateTransition {
   238→        StateTransition {
   239→            pattern_id,
   240→            timestamp,
   241→            from_state,
   242→            to_state,
   243→            frequency_at_transition: frequency,
   244→            confidence_at_transition: confidence,
   245→            reason,
   246→        }
   247→    }
   248→}
   249→
   250→// ============================================================================
   251→// StateMachineManager: 전체 상태 머신 관리
   252→// ============================================================================
   253→
   254→struct StateMachineManager {
   255→    patterns: Vec<PatternLearningState>,
   256→    transitions: Vec<StateTransition>,
   257→}
   258→
   259→impl StateMachineManager {
   260→    fn new() -> StateMachineManager {
   261→        StateMachineManager {
   262→            patterns: Vec::new(),
   263→            transitions: Vec::new(),
   264→        }
   265→    }
   266→
   267→    fn add_pattern(&mut self, pattern_id: u32, pattern_type: String) {
   268→        let state = PatternLearningState::new(pattern_id, pattern_type);
   269→        self.patterns.push(state);
   270→    }
   271→
   272→    fn observe_pattern(&mut self, pattern_id: u32, timestamp: u64, evidence: f64) {
   273→        // 패턴 관찰 및 상태 전이 시도
   274→        for pattern in &mut self.patterns {
   275→            if pattern.pattern_id == pattern_id {
   276→                let old_state = pattern.current_state.clone();
   277→                pattern.observe(timestamp, evidence);
   278→
   279→                if pattern.try_transition(timestamp) {
   280→                    // 상태 전이 발생 -> 로그에 기록
   281→                    let transition = StateTransition::new(
   282→                        pattern_id,
   283→                        timestamp,
   284→                        old_state,
   285→                        pattern.current_state.clone(),
   286→                        pattern.frequency,
   287→                        pattern.confidence,
   288→                        format!("Frequency increased to {}", pattern.frequency),
   289→                    );
   290→                    self.transitions.push(transition);
   291→                }
   292→                return;
   293→            }
   294→        }
   295→    }
   296→
   297→    fn record_prediction(&mut self, pattern_id: u32, success: bool) {
   298→        for pattern in &mut self.patterns {
   299→            if pattern.pattern_id == pattern_id {
   300→                pattern.record_prediction_result(success);
   301→                return;
   302→            }
   303→        }
   304→    }
   305→
   306→    fn get_actionable_patterns(&self) -> Vec<u32> {
   307→        // 현재 조치 가능한 패턴 ID 목록
   308→        self.patterns
   309→            .iter()
   310→            .filter(|p| p.is_actionable())
   311→            .map(|p| p.pattern_id)
   312→            .collect()
   313→    }
   314→
   315→    fn get_pattern_state(&self, pattern_id: u32) -> Option<String> {
   316→        for pattern in &self.patterns {
   317→            if pattern.pattern_id == pattern_id {
   318→                return Some(pattern.current_state.clone());
   319→            }
   320→        }
   321→        None
   322→    }
   323→
   324→    fn get_pattern_confidence(&self, pattern_id: u32) -> Option<f64> {
   325→        for pattern in &self.patterns {
   326→            if pattern.pattern_id == pattern_id {
   327→                return Some(pattern.confidence);
   328→            }
   329→        }
   330→        None
   331→    }
   332→
   333→    fn get_action_confidence(&self, pattern_id: u32) -> Option<f64> {
   334→        for pattern in &self.patterns {
   335→            if pattern.pattern_id == pattern_id {
   336→                return Some(pattern.get_action_confidence());
   337→            }
   338→        }
   339→        None
   340→    }
   341→
   342→    fn update_all_times(&mut self, current_timestamp: u64) {
   343→        for pattern in &mut self.patterns {
   344→            pattern.update_state_time(current_timestamp);
   345→        }
   346→    }
   347→
   348→    fn get_transition_count(&self) -> usize {
   349→        self.transitions.len()
   350→    }
   351→
   352→    fn get_total_patterns(&self) -> usize {
   353→        self.patterns.len()
   354→    }
   355→}
