    pub fn detect_zero_day(&self, pid: u32) -> Option<f64> { ... }

    // 성능 메트릭
    pub fn get_pipeline_latency_stats(&self) -> LatencyStats { ... }

    // 탐지 정확도 (정량)
    pub fn get_accuracy_metrics(&self) -> AccuracyMetrics {
        AccuracyMetrics {
            detection_accuracy: self.classifier.get_accuracy(),
            false_positive_rate: self.classifier.get_false_positive_rate(),
            avg_latency_us: self.avg_detection_latency_ns / 1000,
            p99_latency_us: self.p99_detection_latency_ns / 1000,
        }
    }

    // 격리된 프로세스 목록
    pub fn get_isolated_processes(&self) -> Vec<u32> { ... }
}

pub struct AccuracyMetrics {
    pub detection_accuracy: f64,   // 목표: > 99.9%
    pub false_positive_rate: f64,  // 목표: < 0.1%
    pub avg_latency_us: u64,       // 목표: < 100µs
    pub p99_latency_us: u64,       // 목표: < 100µs
}
```

